  dict(eo="1.3", q="A pump takes suction from a tank. Pa = 30 ft, Pst = 12 ft, hf = 4 ft, and Psat = 2 ft. What is NPSHA?", o=["32 ft", "36 ft", "40 ft", "48 ft"], a=1, x="NPSHA = Pa + Pst - hf - Psat = 30 + 12 - 4 - 2 = 36 ft.", p="rel"),
